DELETE FROM public.user_point_contribution contribution WHERE contribution.id_level=ANY($1) AND contribution.id_user=ANY($2) AND NOT EXISTS(SELECT 1 FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb JOIN public.level_points points ON points.id_level=pb.id_level WHERE pb.id_user=contribution.id_user AND pb.id_level=contribution.id_level AND points.points>0) RETURNING contribution.id_user AS id
